        case source
        case importId = "import_id"
        case kind
    }

    public init(from decoder: any Decoder) throws {
        try StrictKeys.check(decoder, allowed: ["id", "ts", "source", "import_id", "kind"], type: "ObservationIdleStart")
        let c = try decoder.container(keyedBy: CodingKeys.self)
        self.id = try c.decode(String.self, forKey: .id)
        do { let v = self.id
            try Check.pattern(v, #"^[0-7][0-9A-HJKMNP-TV-Z]{25}$"#, field: "id")
        }
        self.ts = try c.decode(String.self, forKey: .ts)
        do { let v = self.ts
            try Check.pattern(v, #"^(?:(?:\d\d[2468][048]|\d\d[13579][26]|\d\d0[48]|[02468][048]00|[13579][26]00)-02-29|\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\d|30)|(?:02)-(?:0[1-9]|1\d|2[0-8])))T(?:(?:[01]\d|2[0-3]):[0-5]\d:[0-5]\d(?:\.\d+)?(?:Z|([+-](?:[01]\d|2[0-3]):[0-5]\d)))$"#, field: "ts")
        }
        self.source = try c.decodeIfPresent(ObservationSource.self, forKey: .source)
        self.importId = try c.decodeIfPresent(String.self, forKey: .importId)
        if let v = self.importId {
            try Check.pattern(v, #"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$"#, field: "import_id")
        }
        guard try c.decode(String.self, forKey: .kind) == "idle_start" else { throw ContractError("ObservationIdleStart: kind must be idle_start") }
    }

    public func encode(to encoder: any Encoder) throws {
        var c = encoder.container(keyedBy: CodingKeys.self)
        try c.encode(id, forKey: .id)
        try c.encode(ts, forKey: .ts)
        try c.encodeIfPresent(source, forKey: .source)
        try c.encodeIfPresent(importId, forKey: .importId)
        try c.encode("idle_start", forKey: .kind)
    }
}

public struct ObservationFocus: Codable, Equatable, Sendable {
    public var id: String
    public var ts: String
    public var source: ObservationSource?
    public var importId: String?
    public var appBundleId: String
    public var appName: String
    public var title: String?
    public var host: String?
    public var doc: String?

    public init(id: String, ts: String, source: ObservationSource? = nil, importId: String? = nil, appBundleId: String, appName: String, title: String? = nil, host: String? = nil, doc: String? = nil) {
        self.id = id
        self.ts = ts
        self.source = source
        self.importId = importId
        self.appBundleId = appBundleId
        self.appName = appName
        self.title = title
        self.host = host
        self.doc = doc
    }

    private enum CodingKeys: String, CodingKey {
        case id
        case ts
        case source
        case importId = "import_id"
        case kind
        case appBundleId = "app_bundle_id"
        case appName = "app_name"
        case title
        case host
        case doc
    }

    public init(from decoder: any Decoder) throws {
        try StrictKeys.check(decoder, allowed: ["id", "ts", "source", "import_id", "kind", "app_bundle_id", "app_name", "title", "host", "doc"], type: "ObservationFocus")
        let c = try decoder.container(keyedBy: CodingKeys.self)
        self.id = try c.decode(String.self, forKey: .id)
        do { let v = self.id
            try Check.pattern(v, #"^[0-7][0-9A-HJKMNP-TV-Z]{25}$"#, field: "id")
        }
        self.ts = try c.decode(String.self, forKey: .ts)
        do { let v = self.ts
            try Check.pattern(v, #"^(?:(?:\d\d[2468][048]|\d\d[13579][26]|\d\d0[48]|[02468][048]00|[13579][26]00)-02-29|\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\d|30)|(?:02)-(?:0[1-9]|1\d|2[0-8])))T(?:(?:[01]\d|2[0-3]):[0-5]\d:[0-5]\d(?:\.\d+)?(?:Z|([+-](?:[01]\d|2[0-3]):[0-5]\d)))$"#, field: "ts")
        }
        self.source = try c.decodeIfPresent(ObservationSource.self, forKey: .source)
        self.importId = try c.decodeIfPresent(String.self, forKey: .importId)
        if let v = self.importId {
            try Check.pattern(v, #"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$"#, field: "import_id")
        }
        guard try c.decode(String.self, forKey: .kind) == "focus" else { throw ContractError("ObservationFocus: kind must be focus") }
        self.appBundleId = try c.decode(String.self, forKey: .appBundleId)
        do { let v = self.appBundleId
            try Check.length(v, min: nil, max: 255, field: "app_bundle_id")
        }
        self.appName = try c.decode(String.self, forKey: .appName)
        do { let v = self.appName
            try Check.length(v, min: nil, max: 256, field: "app_name")
        }
        self.title = try c.decodeIfPresent(String.self, forKey: .title)
        if let v = self.title {
            try Check.length(v, min: nil, max: 512, field: "title")
        }
        self.host = try c.decodeIfPresent(String.self, forKey: .host)
        if let v = self.host {
            try Check.length(v, min: 1, max: 253, field: "host")
            try Check.pattern(v, #"^[A-Za-z0-9]([A-Za-z0-9-]*[A-Za-z0-9])?(\.[A-Za-z0-9]([A-Za-z0-9-]*[A-Za-z0-9])?)*$"#, field: "host")
        }
        self.doc = try c.decodeIfPresent(String.self, forKey: .doc)
        if let v = self.doc {
            try Check.pattern(v, #"^<doc:h_[0-9a-f]{16}>$"#, field: "doc")
        }
    }

    public func encode(to encoder: any Encoder) throws {
        var c = encoder.container(keyedBy: CodingKeys.self)
        try c.encode(id, forKey: .id)
        try c.encode(ts, forKey: .ts)
        try c.encodeIfPresent(source, forKey: .source)
        try c.encodeIfPresent(importId, forKey: .importId)
        try c.encode("focus", forKey: .kind)
        try c.encode(appBundleId, forKey: .appBundleId)
        try c.encode(appName, forKey: .appName)
        try c.encodeIfPresent(title, forKey: .title)
        try c.encodeIfPresent(host, forKey: .host)
        try c.encodeIfPresent(doc, forKey: .doc)
    }
}

